from pathlib import Path

ROOT = Path(__file__).resolve().parent
API = ROOT / 'frontend' / 'src' / 'web' / 'api.py'
FRONTEND_API = ROOT / 'frontend' / 'frontend_api.ts'
DASHBOARD = ROOT / 'frontend' / 'components' / 'dashboard.tsx'
for target in (API, FRONTEND_API, DASHBOARD):
    if not target.exists():
        raise SystemExit(f'Missing target: {target}')

api = API.read_text(encoding='utf-8')
if 'class TradePreviewRequest' not in api:
    marker = 'class UserUpdate(BaseModel):\n'
    insert = '''class TradePreviewRequest(BaseModel):\n    asset: str = Field(min_length=1, max_length=100)\n    timeframe: str = Field(default="1m", min_length=2, max_length=5)\n    amount: float = Field(gt=0)\n    duration: int = Field(default=60, ge=30, le=3600)\n\n\nclass TradeExecuteRequest(TradePreviewRequest):\n    confirm: bool = False\n\n\n_EXECUTION_LOCK = asyncio.Lock()\n_LAST_EXECUTIONS: dict[str, float] = {}\n_EXECUTION_DEDUP_SECONDS = 10.0\n\n\n'''
    if marker not in api: raise SystemExit('Could not locate UserUpdate model')
    api = api.replace(marker, insert + marker, 1)
if 'import asyncio' not in api:
    api = api.replace('import hmac\n', 'import asyncio\nimport hmac\n', 1)
if 'from src.services.risk_manager import RiskManager' not in api:
    api = api.replace('from src.signals.engine import SignalEngine\n', 'from src.signals.engine import SignalEngine\nfrom src.services.risk_manager import RiskManager\n', 1)
if '@app.post("/api/market/trade/preview"' not in api:
    endpoint = '''\n\ndef _dashboard_operator_id() -> int:\n    raw = os.getenv("DASHBOARD_OPERATOR_ID", "").strip()\n    try:\n        value = int(raw)\n    except (TypeError, ValueError):\n        value = 0\n    if value <= 0:\n        raise HTTPException(status_code=503, detail="DASHBOARD_OPERATOR_ID is not configured on the server")\n    return value\n\n\nasync def _fresh_trade_signal(asset: str, timeframe: str) -> dict:\n    timeframe = timeframe.lower().strip()\n    if timeframe not in {"1m", "2m", "5m", "15m", "30m", "1h"}:\n        raise HTTPException(status_code=400, detail=f"Unsupported timeframe: {timeframe}")\n    if asset not in scanner.assets():\n        raise HTTPException(status_code=400, detail=f"Unknown OTC asset: {asset}")\n    await scanner.ensure_connected()\n    if scanner.fetcher is None or scanner.client is None:\n        raise HTTPException(status_code=503, detail="Broker market connection unavailable")\n    candles = await scanner.fetcher.get_historical_data(asset, timeframe=timeframe, count=200)\n    signal_engine.data_fetcher = scanner.fetcher\n    result = await signal_engine.generate_signal(asset=asset, timeframe=timeframe, candles=candles)\n    return {"asset": asset, "timeframe": timeframe, "signal": result}\n\n\nasync def _trade_validation(payload: TradePreviewRequest) -> dict:\n    settings = get_settings(require_token=False)\n    amount = float(payload.amount)\n    duration = int(payload.duration)\n    minimum = float(getattr(settings, "MIN_TRADE_AMOUNT", 0.0))\n    maximum = float(getattr(settings, "MAX_TRADE_AMOUNT", 0.0))\n    if amount < minimum:\n        raise HTTPException(status_code=400, detail=f"Trade amount must be at least {minimum:.2f}")\n    if maximum > 0 and amount > maximum:\n        raise HTTPException(status_code=400, detail=f"Trade amount cannot exceed {maximum:.2f}")\n    if duration not in {30, 60, 120, 300, 600}:\n        raise HTTPException(status_code=400, detail="Unsupported duration. Use 30, 60, 120, 300 or 600 seconds.")\n\n    fresh = await _fresh_trade_signal(payload.asset, payload.timeframe)\n    signal = fresh["signal"]\n    action = str(signal.get("action") or "NO_SIGNAL").upper()\n    confidence = float(signal.get("confidence") or 0.0)\n    balance = None\n    get_balance = getattr(scanner.client, "get_balance", None)\n    if callable(get_balance):\n        try:\n            balance = await get_balance()\n        except Exception:\n            balance = None\n    if balance is not None:\n        balance = float(balance)\n\n    reasons = []\n    if action not in {"CALL", "PUT"}: reasons.append("Signal is not executable.")\n    if confidence < float(getattr(settings, "MIN_CONFIDENCE", 70)): reasons.append("Signal confidence is below the configured minimum.")\n    if balance is None: reasons.append("Broker balance is unavailable.")\n    elif amount > balance: reasons.append("Trade amount exceeds available balance.")\n    if balance is not None:\n        risk = RiskManager(account_balance=balance, max_risk_per_trade=0.02)\n        if risk.should_block(amount, confidence): reasons.append("Risk manager rejected the requested amount/confidence.")\n\n    return {"allowed": not reasons, "reasons": reasons, "asset": fresh["asset"], "timeframe": fresh["timeframe"], "signal": signal, "amount": amount, "duration": duration, "balance": balance, "min_amount": minimum, "max_amount": maximum, "demo_mode": bool(getattr(settings, "DEMO_MODE", True))}\n\n\n@app.post("/api/market/trade/preview", dependencies=[Depends(require_dashboard_key)])\nasync def market_trade_preview(payload: TradePreviewRequest) -> dict:\n    try:\n        return await _trade_validation(payload)\n    except HTTPException:\n        raise\n    except Exception as exc:\n        raise HTTPException(status_code=503, detail=f"Trade preview unavailable: {exc}") from exc\n\n\n@app.post("/api/market/trade/execute", dependencies=[Depends(require_dashboard_key)])\nasync def market_trade_execute(payload: TradeExecuteRequest) -> dict:\n    if not payload.confirm:\n        raise HTTPException(status_code=400, detail="Explicit trade confirmation is required")\n    operator_id = _dashboard_operator_id()\n    async with _EXECUTION_LOCK:\n        preview = await _trade_validation(payload)\n        if not preview["allowed"]:\n            raise HTTPException(status_code=409, detail="Trade blocked: " + " ".join(preview["reasons"]))\n        signal = preview["signal"]\n        direction = str(signal.get("action") or "").upper()\n        amount = float(preview["amount"])\n        duration = int(preview["duration"])\n        asset = preview["asset"]\n        import time as _time\n        dedup_key = f"{asset}|{direction}|{amount:.8f}|{duration}"\n        now_mono = _time.monotonic()\n        previous = _LAST_EXECUTIONS.get(dedup_key)\n        if previous is not None and (now_mono - previous) < _EXECUTION_DEDUP_SECONDS:\n            raise HTTPException(status_code=409, detail="Duplicate execution blocked. Wait a few seconds before submitting the same trade again.")\n        place_trade = getattr(scanner.client, "place_trade", None)\n        if not callable(place_trade):\n            raise HTTPException(status_code=503, detail="Connected broker does not support trade execution")\n        try:\n            result = await place_trade(asset=asset, direction=direction, amount=amount, duration=duration)\n        except TypeError:\n            result = await place_trade(asset, direction, amount, duration)\n        except Exception as exc:\n            raise HTTPException(status_code=502, detail=f"Broker execution failed: {exc}") from exc\n        if not isinstance(result, dict) or not result.get("success") or not result.get("trade_id"):\n            error = result.get("error") if isinstance(result, dict) else "Unknown broker response"\n            raise HTTPException(status_code=502, detail=f"Broker rejected trade: {error}")\n        trade_id = str(result["trade_id"])\n        trade_row_id = DataStorage().save_trade(user_id=operator_id, chat_id=operator_id, asset=asset, direction=direction, amount=amount, duration_secs=duration, order_id=trade_id, entry_price=signal.get("entry_price"))\n        if trade_row_id is None:\n            raise HTTPException(status_code=500, detail="Broker accepted the trade, but local audit recording failed. Reconciliation is required.")\n        _LAST_EXECUTIONS[dedup_key] = now_mono\n        return {"status": "EXECUTED", "trade_id": trade_id, "trade_history_id": trade_row_id, "operator_id": operator_id, "asset": asset, "direction": direction, "amount": amount, "duration": duration, "entry_price": signal.get("entry_price"), "signal_confidence": signal.get("confidence"), "signal_timestamp": signal.get("timestamp"), "demo_mode": preview["demo_mode"]}\n\n'''
    marker = '\n@app.get("/api/market/status"'
    if marker not in api: raise SystemExit('Could not locate market status endpoint')
    api = api.replace(marker, endpoint + marker, 1)
API.write_text(api, encoding='utf-8')

fa = FRONTEND_API.read_text(encoding='utf-8')
if 'export type TradePreview' not in fa:
    fa += '''\n\nexport type TradePreview = {\n  allowed: boolean; reasons: string[]; asset: string; timeframe: string;\n  signal: MarketSignal["signal"]; amount: number; duration: number; balance?: number | null;\n  min_amount?: number; max_amount?: number; demo_mode?: boolean;\n};\n\nexport type TradeExecution = {\n  status: string; trade_id: string; trade_history_id: number; operator_id: number;\n  asset: string; direction: string; amount: number; duration: number; entry_price?: number | null;\n  signal_confidence?: number | null; signal_timestamp?: string | null; demo_mode?: boolean;\n};\n\nexport async function previewTrade(input: { asset: string; timeframe: string; amount: number; duration: number }): Promise<TradePreview> {\n  return dashboardRequest("/api/market/trade/preview", { method: "POST", body: JSON.stringify(input) });\n}\n\nexport async function executeTrade(input: { asset: string; timeframe: string; amount: number; duration: number; confirm: boolean }): Promise<TradeExecution> {\n  return dashboardRequest("/api/market/trade/execute", { method: "POST", body: JSON.stringify(input) });\n}\n'''
FRONTEND_API.write_text(fa, encoding='utf-8')

# UI is intentionally kept as a small insertion after the Phase 4 review gate.
dash = DASHBOARD.read_text(encoding='utf-8')
if 'previewTrade' not in dash:
    old = 'import { generateMarketSignal, getMarketScanner, getMarketStatus, ScannerRow, MarketSignal } from "../frontend_api";'
    new = 'import { generateMarketSignal, getMarketScanner, getMarketStatus, previewTrade, executeTrade, ScannerRow, MarketSignal, TradePreview, TradeExecution } from "../frontend_api";'
    if old not in dash: raise SystemExit('Could not locate dashboard frontend import')
    dash = dash.replace(old, new, 1)

if 'function ExecutionPanel(' not in dash:
    component = r'''\nfunction ExecutionPanel({ signal, timeframe, reviewed }: { signal: MarketSignal; timeframe: string; reviewed: boolean }) {\n  const [amount, setAmount] = useState("1");\n  const [duration, setDuration] = useState("60");\n  const [preview, setPreview] = useState<TradePreview | null>(null);\n  const [result, setResult] = useState<TradeExecution | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState("");\n  const [confirm, setConfirm] = useState(false);\n  if (!reviewed || signal.signal.action === "NO_SIGNAL") return null;\n  async function prepare() {\n    setBusy(true); setError(""); setResult(null); setConfirm(false);\n    try { const p = await previewTrade({ asset: signal.asset, timeframe, amount: Number(amount), duration: Number(duration) }); setPreview(p); if (!p.allowed) setError(p.reasons.join(" ")); }\n    catch (e) { setPreview(null); setError(e instanceof Error ? e.message : "Execution preview failed"); }\n    finally { setBusy(false); }\n  }\n  async function execute() {\n    if (!preview?.allowed || !confirm) return;\n    setBusy(true); setError("");\n    try { const r = await executeTrade({ asset: signal.asset, timeframe, amount: Number(amount), duration: Number(duration), confirm: true }); setResult(r); }\n    catch (e) { setError(e instanceof Error ? e.message : "Trade execution failed"); }\n    finally { setBusy(false); }\n  }\n  return <div style={{ marginTop: 14, padding: 14, border: "1px solid rgba(245,158,11,.28)", borderRadius: 12, background: "rgba(245,158,11,.035)" }}>\n    <div style={{ fontSize: 10, color: "#fbbf24", letterSpacing: ".09em", textTransform: "uppercase" }}>Phase 5 - Controlled Execution</div>\n    <div style={{ fontSize: 17, fontWeight: 800, marginTop: 3 }}>Execution Preview</div>\n    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 9, marginTop: 12 }}>\n      <label style={{ fontSize: 10, color: "#7f8a9d" }}>Amount<input value={amount} onChange={e => setAmount(e.target.value)} type="number" min="0.01" step="0.01" style={{ ...inputStyle, width: "100%", marginTop: 5 }} /></label>\n      <label style={{ fontSize: 10, color: "#7f8a9d" }}>Duration<select value={duration} onChange={e => setDuration(e.target.value)} style={{ ...inputStyle, width: "100%", marginTop: 5 }}><option value="30">30s</option><option value="60">60s</option><option value="120">120s</option><option value="300">300s</option><option value="600">600s</option></select></label>\n    </div>\n    <div style={{ display: "grid", gridTemplateColumns: "repeat(4,minmax(0,1fr))", gap: 7, marginTop: 10 }}><Detail label="Direction" value={signal.signal.action} /><Detail label="Asset" value={signal.asset} /><Detail label="Timeframe" value={timeframe} /><Detail label="Entry" value={fmt(signal.signal.entry_price)} /></div>\n    <button style={primaryButtonStyle} onClick={prepare} disabled={busy}>{busy ? "Checking..." : "Prepare Execution"}</button>\n    {preview && <div style={{ marginTop: 10, padding: 11, border: "1px solid #202733", borderRadius: 9, background: "#0c1118" }}>\n      <div style={{ display: "grid", gridTemplateColumns: "repeat(3,minmax(0,1fr))", gap: 7 }}><Detail label="Balance" value={preview.balance != null ? preview.balance.toFixed(2) : "Unavailable"} /><Detail label="Stake" value={preview.amount.toFixed(2)} /><Detail label="Risk Gate" value={preview.allowed ? "PASSED" : "BLOCKED"} /></div>\n      {preview.reasons.length > 0 && <div style={{ ...errorStyle, marginTop: 9, marginBottom: 0 }}>{preview.reasons.join(" ")}</div>}\n      {preview.allowed && !result && <><label style={{ display: "flex", gap: 8, alignItems: "center", marginTop: 10, fontSize: 11, color: "#aab3c2" }}><input type="checkbox" checked={confirm} onChange={e => setConfirm(e.target.checked)} />I confirm this exact asset, direction, amount and duration for broker execution.</label><button style={{ ...primaryButtonStyle, opacity: confirm ? 1 : .45 }} disabled={!confirm || busy} onClick={execute}>{busy ? "Submitting..." : `Confirm & Execute ${signal.signal.action}`}</button></>}\n    </div>}\n    {result && <div style={{ marginTop: 10, padding: 11, borderRadius: 9, border: "1px solid rgba(74,222,128,.25)", background: "rgba(74,222,128,.05)", fontSize: 11, lineHeight: 1.7 }}><strong style={{ color: "#4ade80" }}>TRADE EXECUTED</strong><br />Broker trade ID: <strong>{result.trade_id}</strong><br />Audit record: <strong>#{result.trade_history_id}</strong><br />{result.demo_mode ? "DEMO ACCOUNT" : "LIVE ACCOUNT"} - {result.asset} - {result.direction} - {result.amount.toFixed(2)} - {result.duration}s</div>}\n    {error && <div style={{ ...errorStyle, marginTop: 9, marginBottom: 0 }}>{error}</div>}\n    <div style={{ marginTop: 9, fontSize: 10, color: "#687386" }}>Server-side validation regenerates the signal immediately before execution. Successful trades use the existing TradeHistory audit path.</div>\n  </div>;\n}\n'''
    marker = '\nfunction Overview()'
    if marker not in dash: raise SystemExit('Could not locate Overview in dashboard.tsx')
    dash = dash.replace(marker, component + marker, 1)

if '<ExecutionPanel signal={signal}' not in dash:
    marker = '''            )}\n          </div>\n        </section>'''
    replacement = '''            )}\n            {signal && <ExecutionPanel signal={signal} timeframe={timeframe} reviewed={signalReviewed} />}\n          </div>\n        </section>'''
    if marker not in dash: raise SystemExit('Could not locate Phase 4 signal block')
    dash = dash.replace(marker, replacement, 1)

DASHBOARD.write_text(dash, encoding='utf-8')
print('Applied Phase 5: controlled execution preview, server-side signal revalidation, risk gates, duplicate protection, broker execution, and TradeHistory audit.')
